    length += coefficients[start_idx + 51] * q_pows[0, 7] * q_pows[1, 2]
    df_dq[0] += coefficients[start_idx + 51] * 7.0 * q_pows[0, 6] * q_pows[1, 2]
    df_dq[1] += coefficients[start_idx + 51] * 2.0 * q_pows[0, 7] * q_pows[1, 1]

    # Coefficient 52: Exponents (8, 0)
    length += coefficients[start_idx + 52] * q_pows[0, 8]
