    length += coefficients[start_idx + 15] * q_pows[0, 1] * q_pows[1, 2]
    df_dq[0] += coefficients[start_idx + 15] * 1.0 * q_pows[1, 2]
    df_dq[1] += coefficients[start_idx + 15] * 2.0 * q_pows[0, 1] * q_pows[1, 1]

