    length += coefficients[start_idx + 16] * q_pows[0, 2]
    df_dq[0] += coefficients[start_idx + 16] * 2.0 * q_pows[0, 1]

    # Coefficient 17: Exponents (2, 0, 1)
    length += coefficients[start_idx + 17] * q_pows[0, 2] * q_pows[2, 1]
    df_dq[0] += coefficients[start_idx + 17] * 2.0 * q_pows[0, 1] * q_pows[2, 1]
    df_dq[2] += coefficients[start_idx + 17] * 1.0 * q_pows[0, 2]

    # Coefficient 18: Exponents (2, 1, 0)
    length += coefficients[start_idx + 18] * q_pows[0, 2] * q_pows[1, 1]
    df_dq[0] += coefficients[start_idx + 18] * 2.0 * q_pows[0, 1] * q_pows[1, 1]
    df_dq[1] += coefficients[start_idx + 18] * 1.0 * q_pows[0, 2]

