    df_dq[1] += coefficients[start_idx + 29] * 1.0 * q_pows[0, 1] * q_pows[2, 3]
    df_dq[2] += coefficients[start_idx + 29] * 3.0 * q_pows[0, 1] * q_pows[1, 1] * q_pows[2, 2]

