    df_dq[2] += coefficients[start_idx + 37] * 1.0 * q_pows[0, 2]

    # Coefficient 38: Exponents (2, 0, 2)
    length += coefficients[start_idx + 38] * q_pows[0, 2] * q_pows[2, 2]
