    df_dq[1] += coefficients[start_idx + 41] * 1.0 * q_pows[0, 2] * q_pows[2, 1]
    df_dq[2] += coefficients[start_idx + 41] * 1.0 * q_pows[0, 2] * q_pows[1, 1]

    # Coefficient 42: Exponents (2, 1, 2)
    length += coefficients[start_idx + 42] * q_pows[0, 2] * q_pows[1, 1] * q_pows[2, 2]
