    # Coefficient 69: Exponents (3, 1, 1)
    length += coefficients[start_idx + 69] * q_pows[0, 3] * q_pows[1, 1] * q_pows[2, 1]
    df_dq[0] += coefficients[start_idx + 69] * 3.0 * q_pows[0, 2] * q_pows[1, 1] * q_pows[2, 1]
    df_dq[1] += coefficients[start_idx + 69] * 1.0 * q_pows[0, 3] * q_pows[2, 1]
    df_dq[2] += coefficients[start_idx + 69] * 1.0 * q_pows[0, 3] * q_pows[1, 1]

    # Coefficient 70: Exponents (3, 1, 2)
