    # Coefficient 77: Exponents (4, 1, 0)
    length += coefficients[start_idx + 77] * q_pows[0, 4] * q_pows[1, 1]
    df_dq[0] += coefficients[start_idx + 77] * 4.0 * q_pows[0, 3] * q_pows[1, 1]
    df_dq[1] += coefficients[start_idx + 77] * 1.0 * q_pows[0, 4]

    # Coefficient 78: Exponents (4, 1, 1)
    length += coefficients[start_idx + 78] * q_pows[0, 4] * q_pows[1, 1] * q_pows[2, 1]
