    df_dq[1] += coefficients[start_idx + 78] * 1.0 * q_pows[0, 4] * q_pows[2, 1]
    df_dq[2] += coefficients[start_idx + 78] * 1.0 * q_pows[0, 4] * q_pows[1, 1]

    # Coefficient 79: Exponents (4, 2, 0)
    length += coefficients[start_idx + 79] * q_pows[0, 4] * q_pows[1, 2]
