    length += coefficients[start_idx + 8] * q_pows[1, 1]
    df_dq[1] += coefficients[start_idx + 8] * 1.0

    # Coefficient 9: Exponents (0, 1, 1)
    length += coefficients[start_idx + 9] * q_pows[1, 1] * q_pows[2, 1]
    df_dq[1] += coefficients[start_idx + 9] * 1.0 * q_pows[2, 1]
    df_dq[2] += coefficients[start_idx + 9] * 1.0 * q_pows[1, 1]

