    length += coefficients[start_idx + 10] * q_pows[1, 1] * q_pows[2, 2]
    df_dq[1] += coefficients[start_idx + 10] * 1.0 * q_pows[2, 2]
    df_dq[2] += coefficients[start_idx + 10] * 2.0 * q_pows[1, 1] * q_pows[2, 1]

