    df_dq[2] += coefficients[start_idx + 14] * 6.0 * q_pows[1, 1] * q_pows[2, 5]

    # Coefficient 15: Exponents (0, 2, 0)
    length += coefficients[start_idx + 15] * q_pows[1, 2]
    df_dq[1] += coefficients[start_idx + 15] * 2.0 * q_pows[1, 1]

    # Coefficient 16: Exponents (0, 2, 1)
    length += coefficients[start_idx + 16] * q_pows[1, 2] * q_pows[2, 1]
