    df_dq[1] += coefficients[start_idx + 18] * 2.0 * q_pows[1, 1] * q_pows[2, 3]
    df_dq[2] += coefficients[start_idx + 18] * 3.0 * q_pows[1, 2] * q_pows[2, 2]

    # Coefficient 19: Exponents (0, 2, 4)
    length += coefficients[start_idx + 19] * q_pows[1, 2] * q_pows[2, 4]
    df_dq[1] += coefficients[start_idx + 19] * 2.0 * q_pows[1, 1] * q_pows[2, 4]
    df_dq[2] += coefficients[start_idx + 19] * 4.0 * q_pows[1, 2] * q_pows[2, 3]

    # Coefficient 20: Exponents (0, 2, 5)
    length += coefficients[start_idx + 20] * q_pows[1, 2] * q_pows[2, 5]
    df_dq[1] += coefficients[start_idx + 20] * 2.0 * q_pows[1, 1] * q_pows[2, 5]
