    df_dq[2] += coefficients[start_idx + 25] * 4.0 * q_pows[1, 3] * q_pows[2, 3]

    # Coefficient 26: Exponents (0, 4, 0)
    length += coefficients[start_idx + 26] * q_pows[1, 4]
