    # Coefficient 28: Exponents (0, 4, 2)
    length += coefficients[start_idx + 28] * q_pows[1, 4] * q_pows[2, 2]
    df_dq[1] += coefficients[start_idx + 28] * 4.0 * q_pows[1, 3] * q_pows[2, 2]
    df_dq[2] += coefficients[start_idx + 28] * 2.0 * q_pows[1, 4] * q_pows[2, 1]

    # Coefficient 29: Exponents (0, 4, 3)
    length += coefficients[start_idx + 29] * q_pows[1, 4] * q_pows[2, 3]
    df_dq[1] += coefficients[start_idx + 29] * 4.0 * q_pows[1, 3] * q_pows[2, 3]
    df_dq[2] += coefficients[start_idx + 29] * 3.0 * q_pows[1, 4] * q_pows[2, 2]

    # Coefficient 30: Exponents (0, 5, 0)
    length += coefficients[start_idx + 30] * q_pows[1, 5]
    df_dq[1] += coefficients[start_idx + 30] * 5.0 * q_pows[1, 4]

    # Coefficient 31: Exponents (0, 5, 1)
    length += coefficients[start_idx + 31] * q_pows[1, 5] * q_pows[2, 1]
