    # Coefficient 32: Exponents (0, 5, 2)
    length += coefficients[start_idx + 32] * q_pows[1, 5] * q_pows[2, 2]
    df_dq[1] += coefficients[start_idx + 32] * 5.0 * q_pows[1, 4] * q_pows[2, 2]
    df_dq[2] += coefficients[start_idx + 32] * 2.0 * q_pows[1, 5] * q_pows[2, 1]

    # Coefficient 33: Exponents (0, 6, 0)
    length += coefficients[start_idx + 33] * q_pows[1, 6]
    df_dq[1] += coefficients[start_idx + 33] * 6.0 * q_pows[1, 5]

    # Coefficient 34: Exponents (0, 6, 1)
    length += coefficients[start_idx + 34] * q_pows[1, 6] * q_pows[2, 1]
    df_dq[1] += coefficients[start_idx + 34] * 6.0 * q_pows[1, 5] * q_pows[2, 1]
    df_dq[2] += coefficients[start_idx + 34] * 1.0 * q_pows[1, 6]

    # Coefficient 35: Exponents (0, 7, 0)
    length += coefficients[start_idx + 35] * q_pows[1, 7]
    df_dq[1] += coefficients[start_idx + 35] * 7.0 * q_pows[1, 6]

    # Coefficient 36: Exponents (1, 0, 0)
    length += coefficients[start_idx + 36] * q_pows[0, 1]
    df_dq[0] += coefficients[start_idx + 36] * 1.0

    # Coefficient 37: Exponents (1, 0, 1)
    length += coefficients[start_idx + 37] * q_pows[0, 1] * q_pows[2, 1]
