    length += coefficients[start_idx + 39] * q_pows[0, 1] * q_pows[2, 3]
    df_dq[0] += coefficients[start_idx + 39] * 1.0 * q_pows[2, 3]
    df_dq[2] += coefficients[start_idx + 39] * 3.0 * q_pows[0, 1] * q_pows[2, 2]

    # Coefficient 40: Exponents (1, 0, 4)
    length += coefficients[start_idx + 40] * q_pows[0, 1] * q_pows[2, 4]
    df_dq[0] += coefficients[start_idx + 40] * 1.0 * q_pows[2, 4]
    df_dq[2] += coefficients[start_idx + 40] * 4.0 * q_pows[0, 1] * q_pows[2, 3]

    # Coefficient 41: Exponents (1, 0, 5)
    length += coefficients[start_idx + 41] * q_pows[0, 1] * q_pows[2, 5]
    df_dq[0] += coefficients[start_idx + 41] * 1.0 * q_pows[2, 5]
    df_dq[2] += coefficients[start_idx + 41] * 5.0 * q_pows[0, 1] * q_pows[2, 4]

    # Coefficient 42: Exponents (1, 0, 6)
    length += coefficients[start_idx + 42] * q_pows[0, 1] * q_pows[2, 6]
    df_dq[0] += coefficients[start_idx + 42] * 1.0 * q_pows[2, 6]
    df_dq[2] += coefficients[start_idx + 42] * 6.0 * q_pows[0, 1] * q_pows[2, 5]

    # Coefficient 43: Exponents (1, 1, 0)
    length += coefficients[start_idx + 43] * q_pows[0, 1] * q_pows[1, 1]
    df_dq[0] += coefficients[start_idx + 43] * 1.0 * q_pows[1, 1]
    df_dq[1] += coefficients[start_idx + 43] * 1.0 * q_pows[0, 1]

    # Coefficient 44: Exponents (1, 1, 1)
    length += coefficients[start_idx + 44] * q_pows[0, 1] * q_pows[1, 1] * q_pows[2, 1]
    df_dq[0] += coefficients[start_idx + 44] * 1.0 * q_pows[1, 1] * q_pows[2, 1]
    df_dq[1] += coefficients[start_idx + 44] * 1.0 * q_pows[0, 1] * q_pows[2, 1]
