    df_dq[1] += coefficients[start_idx + 45] * 1.0 * q_pows[0, 1] * q_pows[2, 2]
    df_dq[2] += coefficients[start_idx + 45] * 2.0 * q_pows[0, 1] * q_pows[1, 1] * q_pows[2, 1]

    # Coefficient 46: Exponents (1, 1, 3)
    length += coefficients[start_idx + 46] * q_pows[0, 1] * q_pows[1, 1] * q_pows[2, 3]
    df_dq[0] += coefficients[start_idx + 46] * 1.0 * q_pows[1, 1] * q_pows[2, 3]
    df_dq[1] += coefficients[start_idx + 46] * 1.0 * q_pows[0, 1] * q_pows[2, 3]
    df_dq[2] += coefficients[start_idx + 46] * 3.0 * q_pows[0, 1] * q_pows[1, 1] * q_pows[2, 2]

    # Coefficient 47: Exponents (1, 1, 4)
    length += coefficients[start_idx + 47] * q_pows[0, 1] * q_pows[1, 1] * q_pows[2, 4]
