    df_dq[0] += coefficients[start_idx + 169] * 2.0 * q_pows[0, 1] * q_pows[1, 2] * q_pows[2, 1] * q_pows[3, 1]
    df_dq[1] += coefficients[start_idx + 169] * 2.0 * q_pows[0, 2] * q_pows[1, 1] * q_pows[2, 1] * q_pows[3, 1]
    df_dq[2] += coefficients[start_idx + 169] * 1.0 * q_pows[0, 2] * q_pows[1, 2] * q_pows[3, 1]
    df_dq[3] += coefficients[start_idx + 169] * 1.0 * q_pows[0, 2] * q_pows[1, 2] * q_pows[2, 1]

    # Coefficient 170: Exponents (2, 2, 2, 0)
