    df_dq[2] += coefficients[start_idx + 182] * 2.0 * q_pows[0, 3] * q_pows[2, 1]

    # Coefficient 183: Exponents (3, 0, 2, 1)
    length += coefficients[start_idx + 183] * q_pows[0, 3] * q_pows[2, 2] * q_pows[3, 1]
