    df_dq[2] += coefficients[start_idx + 183] * 2.0 * q_pows[0, 3] * q_pows[2, 1] * q_pows[3, 1]
    df_dq[3] += coefficients[start_idx + 183] * 1.0 * q_pows[0, 3] * q_pows[2, 2]

    # Coefficient 184: Exponents (3, 0, 3, 0)
    length += coefficients[start_idx + 184] * q_pows[0, 3] * q_pows[2, 3]
    df_dq[0] += coefficients[start_idx + 184] * 3.0 * q_pows[0, 2] * q_pows[2, 3]
