    df_dq[1] += coefficients[start_idx + 187] * 1.0 * q_pows[0, 3] * q_pows[3, 2]
    df_dq[3] += coefficients[start_idx + 187] * 2.0 * q_pows[0, 3] * q_pows[1, 1] * q_pows[3, 1]

