    df_dq[5] += coefficients[start_idx + 28] * 1.0 * q_pows[4, 2]

    # Coefficient 29: Exponents (0, 0, 0, 0, 2, 1, 1)
    length += coefficients[start_idx + 29] * q_pows[4, 2] * q_pows[5, 1] * q_pows[6, 1]
    df_dq[4] += coefficients[start_idx + 29] * 2.0 * q_pows[4, 1] * q_pows[5, 1] * q_pows[6, 1]
