    # Coefficient 49: Exponents (0, 0, 0, 1, 1, 1, 1)
    length += coefficients[start_idx + 49] * q_pows[3, 1] * q_pows[4, 1] * q_pows[5, 1] * q_pows[6, 1]
    df_dq[3] += coefficients[start_idx + 49] * 1.0 * q_pows[4, 1] * q_pows[5, 1] * q_pows[6, 1]
    df_dq[4] += coefficients[start_idx + 49] * 1.0 * q_pows[3, 1] * q_pows[5, 1] * q_pows[6, 1]
    df_dq[5] += coefficients[start_idx + 49] * 1.0 * q_pows[3, 1] * q_pows[4, 1] * q_pows[6, 1]
    df_dq[6] += coefficients[start_idx + 49] * 1.0 * q_pows[3, 1] * q_pows[4, 1] * q_pows[5, 1]

    # Coefficient 50: Exponents (0, 0, 0, 1, 1, 2, 0)
