    df_dq[6] += coefficients[start_idx + 52] * 1.0 * q_pows[3, 1] * q_pows[4, 2]

    # Coefficient 53: Exponents (0, 0, 0, 1, 2, 1, 0)
    length += coefficients[start_idx + 53] * q_pows[3, 1] * q_pows[4, 2] * q_pows[5, 1]
