    df_dq[7] += coefficients[start_idx + 16] * 1.0 * q_pows[5, 1]

    # Coefficient 17: Exponents (0, 0, 0, 0, 0, 1, 0, 2)
    length += coefficients[start_idx + 17] * q_pows[5, 1] * q_pows[7, 2]
    df_dq[5] += coefficients[start_idx + 17] * 1.0 * q_pows[7, 2]
    df_dq[7] += coefficients[start_idx + 17] * 2.0 * q_pows[5, 1] * q_pows[7, 1]

