    length += coefficients[start_idx + 18] * q_pows[5, 1] * q_pows[7, 3]
    df_dq[5] += coefficients[start_idx + 18] * 1.0 * q_pows[7, 3]
    df_dq[7] += coefficients[start_idx + 18] * 3.0 * q_pows[5, 1] * q_pows[7, 2]

    # Coefficient 19: Exponents (0, 0, 0, 0, 0, 1, 1, 0)
    length += coefficients[start_idx + 19] * q_pows[5, 1] * q_pows[6, 1]
