    length += coefficients[start_idx + 20] * q_pows[5, 1] * q_pows[6, 1] * q_pows[7, 1]
    df_dq[5] += coefficients[start_idx + 20] * 1.0 * q_pows[6, 1] * q_pows[7, 1]
    df_dq[6] += coefficients[start_idx + 20] * 1.0 * q_pows[5, 1] * q_pows[7, 1]
    df_dq[7] += coefficients[start_idx + 20] * 1.0 * q_pows[5, 1] * q_pows[6, 1]

    # Coefficient 21: Exponents (0, 0, 0, 0, 0, 1, 1, 2)
    length += coefficients[start_idx + 21] * q_pows[5, 1] * q_pows[6, 1] * q_pows[7, 2]
    df_dq[5] += coefficients[start_idx + 21] * 1.0 * q_pows[6, 1] * q_pows[7, 2]
    df_dq[6] += coefficients[start_idx + 21] * 1.0 * q_pows[5, 1] * q_pows[7, 2]
    df_dq[7] += coefficients[start_idx + 21] * 2.0 * q_pows[5, 1] * q_pows[6, 1] * q_pows[7, 1]

    # Coefficient 22: Exponents (0, 0, 0, 0, 0, 1, 2, 0)
    length += coefficients[start_idx + 22] * q_pows[5, 1] * q_pows[6, 2]
    df_dq[5] += coefficients[start_idx + 22] * 1.0 * q_pows[6, 2]
    df_dq[6] += coefficients[start_idx + 22] * 2.0 * q_pows[5, 1] * q_pows[6, 1]

    # Coefficient 23: Exponents (0, 0, 0, 0, 0, 1, 2, 1)
    length += coefficients[start_idx + 23] * q_pows[5, 1] * q_pows[6, 2] * q_pows[7, 1]
    df_dq[5] += coefficients[start_idx + 23] * 1.0 * q_pows[6, 2] * q_pows[7, 1]
    df_dq[6] += coefficients[start_idx + 23] * 2.0 * q_pows[5, 1] * q_pows[6, 1] * q_pows[7, 1]
    df_dq[7] += coefficients[start_idx + 23] * 1.0 * q_pows[5, 1] * q_pows[6, 2]

    # Coefficient 24: Exponents (0, 0, 0, 0, 0, 1, 3, 0)
    length += coefficients[start_idx + 24] * q_pows[5, 1] * q_pows[6, 3]
    df_dq[5] += coefficients[start_idx + 24] * 1.0 * q_pows[6, 3]
    df_dq[6] += coefficients[start_idx + 24] * 3.0 * q_pows[5, 1] * q_pows[6, 2]

    # Coefficient 25: Exponents (0, 0, 0, 0, 0, 2, 0, 0)
    length += coefficients[start_idx + 25] * q_pows[5, 2]
    df_dq[5] += coefficients[start_idx + 25] * 2.0 * q_pows[5, 1]

    # Coefficient 26: Exponents (0, 0, 0, 0, 0, 2, 0, 1)
    length += coefficients[start_idx + 26] * q_pows[5, 2] * q_pows[7, 1]
    df_dq[5] += coefficients[start_idx + 26] * 2.0 * q_pows[5, 1] * q_pows[7, 1]
    df_dq[7] += coefficients[start_idx + 26] * 1.0 * q_pows[5, 2]

    # Coefficient 27: Exponents (0, 0, 0, 0, 0, 2, 0, 2)
    length += coefficients[start_idx + 27] * q_pows[5, 2] * q_pows[7, 2]
    df_dq[5] += coefficients[start_idx + 27] * 2.0 * q_pows[5, 1] * q_pows[7, 2]
    df_dq[7] += coefficients[start_idx + 27] * 2.0 * q_pows[5, 2] * q_pows[7, 1]

    # Coefficient 28: Exponents (0, 0, 0, 0, 0, 2, 1, 0)
    length += coefficients[start_idx + 28] * q_pows[5, 2] * q_pows[6, 1]
    df_dq[5] += coefficients[start_idx + 28] * 2.0 * q_pows[5, 1] * q_pows[6, 1]
    df_dq[6] += coefficients[start_idx + 28] * 1.0 * q_pows[5, 2]

    # Coefficient 29: Exponents (0, 0, 0, 0, 0, 2, 1, 1)
    length += coefficients[start_idx + 29] * q_pows[5, 2] * q_pows[6, 1] * q_pows[7, 1]
    df_dq[5] += coefficients[start_idx + 29] * 2.0 * q_pows[5, 1] * q_pows[6, 1] * q_pows[7, 1]
    df_dq[6] += coefficients[start_idx + 29] * 1.0 * q_pows[5, 2] * q_pows[7, 1]
    df_dq[7] += coefficients[start_idx + 29] * 1.0 * q_pows[5, 2] * q_pows[6, 1]

    # Coefficient 30: Exponents (0, 0, 0, 0, 0, 2, 2, 0)
    length += coefficients[start_idx + 30] * q_pows[5, 2] * q_pows[6, 2]
    df_dq[5] += coefficients[start_idx + 30] * 2.0 * q_pows[5, 1] * q_pows[6, 2]
    df_dq[6] += coefficients[start_idx + 30] * 2.0 * q_pows[5, 2] * q_pows[6, 1]

    # Coefficient 31: Exponents (0, 0, 0, 0, 0, 3, 0, 0)
    length += coefficients[start_idx + 31] * q_pows[5, 3]
    df_dq[5] += coefficients[start_idx + 31] * 3.0 * q_pows[5, 2]

    # Coefficient 32: Exponents (0, 0, 0, 0, 0, 3, 0, 1)
    length += coefficients[start_idx + 32] * q_pows[5, 3] * q_pows[7, 1]
    df_dq[5] += coefficients[start_idx + 32] * 3.0 * q_pows[5, 2] * q_pows[7, 1]
    df_dq[7] += coefficients[start_idx + 32] * 1.0 * q_pows[5, 3]

    # Coefficient 33: Exponents (0, 0, 0, 0, 0, 3, 1, 0)
    length += coefficients[start_idx + 33] * q_pows[5, 3] * q_pows[6, 1]
    df_dq[5] += coefficients[start_idx + 33] * 3.0 * q_pows[5, 2] * q_pows[6, 1]
    df_dq[6] += coefficients[start_idx + 33] * 1.0 * q_pows[5, 3]

    # Coefficient 34: Exponents (0, 0, 0, 0, 0, 4, 0, 0)
    length += coefficients[start_idx + 34] * q_pows[5, 4]
    df_dq[5] += coefficients[start_idx + 34] * 4.0 * q_pows[5, 3]

    # Coefficient 35: Exponents (0, 0, 0, 0, 1, 0, 0, 0)
    length += coefficients[start_idx + 35] * q_pows[4, 1]
    df_dq[4] += coefficients[start_idx + 35] * 1.0

    # Coefficient 36: Exponents (0, 0, 0, 0, 1, 0, 0, 1)
    length += coefficients[start_idx + 36] * q_pows[4, 1] * q_pows[7, 1]
    df_dq[4] += coefficients[start_idx + 36] * 1.0 * q_pows[7, 1]
    df_dq[7] += coefficients[start_idx + 36] * 1.0 * q_pows[4, 1]

    # Coefficient 37: Exponents (0, 0, 0, 0, 1, 0, 0, 2)
    length += coefficients[start_idx + 37] * q_pows[4, 1] * q_pows[7, 2]
    df_dq[4] += coefficients[start_idx + 37] * 1.0 * q_pows[7, 2]
    df_dq[7] += coefficients[start_idx + 37] * 2.0 * q_pows[4, 1] * q_pows[7, 1]

    # Coefficient 38: Exponents (0, 0, 0, 0, 1, 0, 0, 3)
    length += coefficients[start_idx + 38] * q_pows[4, 1] * q_pows[7, 3]
    df_dq[4] += coefficients[start_idx + 38] * 1.0 * q_pows[7, 3]
    df_dq[7] += coefficients[start_idx + 38] * 3.0 * q_pows[4, 1] * q_pows[7, 2]

    # Coefficient 39: Exponents (0, 0, 0, 0, 1, 0, 1, 0)
    length += coefficients[start_idx + 39] * q_pows[4, 1] * q_pows[6, 1]
    df_dq[4] += coefficients[start_idx + 39] * 1.0 * q_pows[6, 1]
    df_dq[6] += coefficients[start_idx + 39] * 1.0 * q_pows[4, 1]

    # Coefficient 40: Exponents (0, 0, 0, 0, 1, 0, 1, 1)
    length += coefficients[start_idx + 40] * q_pows[4, 1] * q_pows[6, 1] * q_pows[7, 1]
    df_dq[4] += coefficients[start_idx + 40] * 1.0 * q_pows[6, 1] * q_pows[7, 1]
