    # Coefficient 47: Exponents (0, 0, 0, 0, 1, 1, 0, 2)
    length += coefficients[start_idx + 47] * q_pows[4, 1] * q_pows[5, 1] * q_pows[7, 2]
    df_dq[4] += coefficients[start_idx + 47] * 1.0 * q_pows[5, 1] * q_pows[7, 2]
    df_dq[5] += coefficients[start_idx + 47] * 1.0 * q_pows[4, 1] * q_pows[7, 2]
    df_dq[7] += coefficients[start_idx + 47] * 2.0 * q_pows[4, 1] * q_pows[5, 1] * q_pows[7, 1]

    # Coefficient 48: Exponents (0, 0, 0, 0, 1, 1, 1, 0)
    length += coefficients[start_idx + 48] * q_pows[4, 1] * q_pows[5, 1] * q_pows[6, 1]
    df_dq[4] += coefficients[start_idx + 48] * 1.0 * q_pows[5, 1] * q_pows[6, 1]
    df_dq[5] += coefficients[start_idx + 48] * 1.0 * q_pows[4, 1] * q_pows[6, 1]
    df_dq[6] += coefficients[start_idx + 48] * 1.0 * q_pows[4, 1] * q_pows[5, 1]

    # Coefficient 49: Exponents (0, 0, 0, 0, 1, 1, 1, 1)
    length += coefficients[start_idx + 49] * q_pows[4, 1] * q_pows[5, 1] * q_pows[6, 1] * q_pows[7, 1]
    df_dq[4] += coefficients[start_idx + 49] * 1.0 * q_pows[5, 1] * q_pows[6, 1] * q_pows[7, 1]
    df_dq[5] += coefficients[start_idx + 49] * 1.0 * q_pows[4, 1] * q_pows[6, 1] * q_pows[7, 1]
    df_dq[6] += coefficients[start_idx + 49] * 1.0 * q_pows[4, 1] * q_pows[5, 1] * q_pows[7, 1]
    df_dq[7] += coefficients[start_idx + 49] * 1.0 * q_pows[4, 1] * q_pows[5, 1] * q_pows[6, 1]

