    df_dq[3] += coefficients[start_idx + 491] * 1.0 * q_pows[0, 3]

    # Coefficient 492: Exponents (3, 0, 1, 0, 0, 0, 0, 0)
    length += coefficients[start_idx + 492] * q_pows[0, 3] * q_pows[2, 1]
