    df_dq[2] += coefficients[start_idx + 492] * 1.0 * q_pows[0, 3]

    # Coefficient 493: Exponents (3, 1, 0, 0, 0, 0, 0, 0)
    length += coefficients[start_idx + 493] * q_pows[0, 3] * q_pows[1, 1]
