    length += coefficients[start_idx + 6] * q_pows[7, 1] * q_pows[8, 1]
    df_dq[7] += coefficients[start_idx + 6] * 1.0 * q_pows[8, 1]
    df_dq[8] += coefficients[start_idx + 6] * 1.0 * q_pows[7, 1]

    # Coefficient 7: Exponents (0, 0, 0, 0, 0, 0, 0, 1, 2)
    length += coefficients[start_idx + 7] * q_pows[7, 1] * q_pows[8, 2]
    df_dq[7] += coefficients[start_idx + 7] * 1.0 * q_pows[8, 2]
    df_dq[8] += coefficients[start_idx + 7] * 2.0 * q_pows[7, 1] * q_pows[8, 1]

