    length += coefficients[start_idx + 8] * q_pows[7, 1] * q_pows[8, 3]
    df_dq[7] += coefficients[start_idx + 8] * 1.0 * q_pows[8, 3]
    df_dq[8] += coefficients[start_idx + 8] * 3.0 * q_pows[7, 1] * q_pows[8, 2]

