    length += coefficients[start_idx + 10] * q_pows[7, 2] * q_pows[8, 1]
    df_dq[7] += coefficients[start_idx + 10] * 2.0 * q_pows[7, 1] * q_pows[8, 1]
    df_dq[8] += coefficients[start_idx + 10] * 1.0 * q_pows[7, 2]

