    df_dq[7] += coefficients[start_idx + 24] * 3.0 * q_pows[6, 1] * q_pows[7, 2]

    # Coefficient 25: Exponents (0, 0, 0, 0, 0, 0, 2, 0, 0)
    length += coefficients[start_idx + 25] * q_pows[6, 2]
