    df_dq[7] += coefficients[start_idx + 690] * 1.0 * q_pows[0, 2] * q_pows[2, 1]

    # Coefficient 691: Exponents (2, 0, 1, 0, 0, 0, 1, 0, 0)
    length += coefficients[start_idx + 691] * q_pows[0, 2] * q_pows[2, 1] * q_pows[6, 1]
