    df_dq[1] += coefficients[start_idx + 696] * 1.0 * q_pows[0, 2]

    # Coefficient 697: Exponents (2, 1, 0, 0, 0, 0, 0, 0, 1)
    length += coefficients[start_idx + 697] * q_pows[0, 2] * q_pows[1, 1] * q_pows[8, 1]
