    df_dq[5] += coefficients[start_idx + 968] * 1.0 * q_pows[0, 2] * q_pows[3, 1]

    # Coefficient 969: Exponents (2, 0, 0, 1, 1, 0, 0, 0, 0, 0)
    length += coefficients[start_idx + 969] * q_pows[0, 2] * q_pows[3, 1] * q_pows[4, 1]
