    df_dq[5] += coefficients[start_idx + 976] * 1.0 * q_pows[0, 2] * q_pows[2, 1]

    # Coefficient 977: Exponents (2, 0, 1, 0, 1, 0, 0, 0, 0, 0)
    length += coefficients[start_idx + 977] * q_pows[0, 2] * q_pows[2, 1] * q_pows[4, 1]
    df_dq[0] += coefficients[start_idx + 977] * 2.0 * q_pows[0, 1] * q_pows[2, 1] * q_pows[4, 1]
    df_dq[2] += coefficients[start_idx + 977] * 1.0 * q_pows[0, 2] * q_pows[4, 1]
    df_dq[4] += coefficients[start_idx + 977] * 1.0 * q_pows[0, 2] * q_pows[2, 1]

    # Coefficient 978: Exponents (2, 0, 1, 1, 0, 0, 0, 0, 0, 0)
    length += coefficients[start_idx + 978] * q_pows[0, 2] * q_pows[2, 1] * q_pows[3, 1]
