    df_dq[2] += coefficients[start_idx + 979] * 2.0 * q_pows[0, 2] * q_pows[2, 1]

    # Coefficient 980: Exponents (2, 1, 0, 0, 0, 0, 0, 0, 0, 0)
    length += coefficients[start_idx + 980] * q_pows[0, 2] * q_pows[1, 1]
    df_dq[0] += coefficients[start_idx + 980] * 2.0 * q_pows[0, 1] * q_pows[1, 1]
    df_dq[1] += coefficients[start_idx + 980] * 1.0 * q_pows[0, 2]

    # Coefficient 981: Exponents (2, 1, 0, 0, 0, 0, 0, 0, 0, 1)
    length += coefficients[start_idx + 981] * q_pows[0, 2] * q_pows[1, 1] * q_pows[9, 1]
