    df_dq[8] += coefficients[start_idx + 982] * 1.0 * q_pows[0, 2] * q_pows[1, 1]

    # Coefficient 983: Exponents (2, 1, 0, 0, 0, 0, 0, 1, 0, 0)
    length += coefficients[start_idx + 983] * q_pows[0, 2] * q_pows[1, 1] * q_pows[7, 1]
