    df_dq[1] += coefficients[start_idx + 983] * 1.0 * q_pows[0, 2] * q_pows[7, 1]
    df_dq[7] += coefficients[start_idx + 983] * 1.0 * q_pows[0, 2] * q_pows[1, 1]

    # Coefficient 984: Exponents (2, 1, 0, 0, 0, 0, 1, 0, 0, 0)
    length += coefficients[start_idx + 984] * q_pows[0, 2] * q_pows[1, 1] * q_pows[6, 1]
    df_dq[0] += coefficients[start_idx + 984] * 2.0 * q_pows[0, 1] * q_pows[1, 1] * q_pows[6, 1]
    df_dq[1] += coefficients[start_idx + 984] * 1.0 * q_pows[0, 2] * q_pows[6, 1]
    df_dq[6] += coefficients[start_idx + 984] * 1.0 * q_pows[0, 2] * q_pows[1, 1]

    # Coefficient 985: Exponents (2, 1, 0, 0, 0, 1, 0, 0, 0, 0)
    length += coefficients[start_idx + 985] * q_pows[0, 2] * q_pows[1, 1] * q_pows[5, 1]
    df_dq[0] += coefficients[start_idx + 985] * 2.0 * q_pows[0, 1] * q_pows[1, 1] * q_pows[5, 1]
    df_dq[1] += coefficients[start_idx + 985] * 1.0 * q_pows[0, 2] * q_pows[5, 1]
    df_dq[5] += coefficients[start_idx + 985] * 1.0 * q_pows[0, 2] * q_pows[1, 1]

    # Coefficient 986: Exponents (2, 1, 0, 0, 1, 0, 0, 0, 0, 0)
    length += coefficients[start_idx + 986] * q_pows[0, 2] * q_pows[1, 1] * q_pows[4, 1]
    df_dq[0] += coefficients[start_idx + 986] * 2.0 * q_pows[0, 1] * q_pows[1, 1] * q_pows[4, 1]
    df_dq[1] += coefficients[start_idx + 986] * 1.0 * q_pows[0, 2] * q_pows[4, 1]
    df_dq[4] += coefficients[start_idx + 986] * 1.0 * q_pows[0, 2] * q_pows[1, 1]

    # Coefficient 987: Exponents (2, 1, 0, 1, 0, 0, 0, 0, 0, 0)
    length += coefficients[start_idx + 987] * q_pows[0, 2] * q_pows[1, 1] * q_pows[3, 1]
    df_dq[0] += coefficients[start_idx + 987] * 2.0 * q_pows[0, 1] * q_pows[1, 1] * q_pows[3, 1]
    df_dq[1] += coefficients[start_idx + 987] * 1.0 * q_pows[0, 2] * q_pows[3, 1]
    df_dq[3] += coefficients[start_idx + 987] * 1.0 * q_pows[0, 2] * q_pows[1, 1]

    # Coefficient 988: Exponents (2, 1, 1, 0, 0, 0, 0, 0, 0, 0)
    length += coefficients[start_idx + 988] * q_pows[0, 2] * q_pows[1, 1] * q_pows[2, 1]
    df_dq[0] += coefficients[start_idx + 988] * 2.0 * q_pows[0, 1] * q_pows[1, 1] * q_pows[2, 1]
    df_dq[1] += coefficients[start_idx + 988] * 1.0 * q_pows[0, 2] * q_pows[2, 1]
    df_dq[2] += coefficients[start_idx + 988] * 1.0 * q_pows[0, 2] * q_pows[1, 1]

    # Coefficient 989: Exponents (2, 2, 0, 0, 0, 0, 0, 0, 0, 0)
    length += coefficients[start_idx + 989] * q_pows[0, 2] * q_pows[1, 2]
    df_dq[0] += coefficients[start_idx + 989] * 2.0 * q_pows[0, 1] * q_pows[1, 2]
    df_dq[1] += coefficients[start_idx + 989] * 2.0 * q_pows[0, 2] * q_pows[1, 1]

